import Base

type LPStatus is Data:
  LPBroken{}
  LPProven{}
  LPDraft{}

def is_lp_proven(s: LPStatus) -> Bool:
  match s:
    case LPBroken{}: False{}
    case LPProven{}: True{}
    case LPDraft{}: False{}

def classify_lattice_proof_status(has_viol: Bool, has_comp: Bool, comp_ok: Bool, flow_ok: Bool) -> LPStatus:
  match has_viol has_comp comp_ok flow_ok:
    case True{} has_comp comp_ok flow_ok:
      LPBroken{}
    case False{} True{} True{} True{}:
      LPProven{}
    case False{} True{} True{} False{}:
      LPDraft{}
    case False{} True{} False{} flow_ok:
      LPDraft{}
    case False{} False{} comp_ok flow_ok:
      LPDraft{}

law lattice_proof_proven_iff_complete_and_conflict_free:
  for +has_viol: Bool
  for +has_comp: Bool
  for +comp_ok: Bool
  for +flow_ok: Bool
  {is_lp_proven(classify_lattice_proof_status(has_viol, has_comp, comp_ok, flow_ok)) == Bool.and(Bool.not(has_viol), Bool.and(has_comp, Bool.and(comp_ok, flow_ok))) : Bool}

def lattice_proof_proven_iff_complete_and_conflict_free(has_viol, has_comp, comp_ok, flow_ok):
  match has_viol has_comp comp_ok flow_ok:
    case True{} has_comp comp_ok flow_ok: {==}
    case False{} True{} True{} True{}: {==}
    case False{} True{} True{} False{}: {==}
    case False{} True{} False{} flow_ok: {==}
    case False{} False{} comp_ok flow_ok: {==}

def board_proof_verdict() -> LPStatus:
  classify_lattice_proof_status(False{}, True{}, True{}, True{})
